// // // // // // // // // // // // // // // // // // //   return String(Math.floor(1000 + Math.random() * 9000));
// // // // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // // 1) CREATE ROOM
// // // // // // // // // // // // // // // // // // // // Frontend sends: { roomName, roomType, maxPlayers, playerName }
// // // // // // // // // // // // // // // // // // // // Backend: saves a new row in word_scramble_rooms + first player in word_scramble_players
// // // // // // // // // // // // // // // // // // // // Response: room details as JSON
// // // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // router.post("/rooms", async (req, res) => {
// // // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // // //     const { roomName, roomType, maxPlayers, playerName } = req.body;

// // // // // // // // // // // // // // // // // // //     if (!playerName) {
// // // // // // // // // // // // // // // // // // //       return res.status(400).json({ error: "playerName is required" });
// // // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // // //     const roomCode = generateRoomCode();

// // // // // // // // // // // // // // // // // // //     // Save room to database
// // // // // // // // // // // // // // // // // // //     const [roomResult] = await db.query(
// // // // // // // // // // // // // // // // // // //       `INSERT INTO word_scramble_rooms (room_code, room_name, room_type, max_players, status)
// // // // // // // // // // // // // // // // // // //        VALUES (?, ?, ?, ?, 'waiting')`,
// // // // // // // // // // // // // // // // // // //       [roomCode, roomName || "FunRoom", roomType || "public", maxPlayers || 4]
// // // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // // //     const roomId = roomResult.insertId;

// // // // // // // // // // // // // // // // // // //     // Save the host/first player to database
// // // // // // // // // // // // // // // // // // //     await db.query(
// // // // // // // // // // // // // // // // // // //       `INSERT INTO word_scramble_players (room_id, player_name, is_ready)
// // // // // // // // // // // // // // // // // // //        VALUES (?, ?, TRUE)`,
// // // // // // // // // // // // // // // // // // //       [roomId, playerName]
// // // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // // //     // Fetch full room + players to send back
// // // // // // // // // // // // // // // // // // //     const [players] = await db.query(
// // // // // // // // // // // // // // // // // // //       `SELECT id, player_name, is_ready, score FROM word_scramble_players WHERE room_id = ?`,
// // // // // // // // // // // // // // // // // // //       [roomId]
// // // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // // //     return res.status(201).json({
// // // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // // //       room: {
// // // // // // // // // // // // // // // // // // //         id: roomId,
// // // // // // // // // // // // // // // // // // //         roomCode,
// // // // // // // // // // // // // // // // // // //         roomName: roomName || "FunRoom",
// // // // // // // // // // // // // // // // // // //         roomType: roomType || "public",
// // // // // // // // // // // // // // // // // // //         maxPlayers: maxPlayers || 4,
// // // // // // // // // // // // // // // // // // //         status: "waiting",
// // // // // // // // // // // // // // // // // // //         players,
// // // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // // //     console.error("Create room error:", err);
// // // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to create room" });
// // // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // // 2) JOIN ROOM
// // // // // // // // // // // // // // // // // // // // Frontend sends: { roomCode, playerName }
// // // // // // // // // // // // // // // // // // // // Backend: finds room by code, inserts player, returns updated room
// // // // // // // // // // // // // // // // // // // // ---------------------------------------------
