// // // // // // // // // // // // // // // // // //         status: room.status,
// // // // // // // // // // // // // // // // // //         players,
// // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Join room error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to join room" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 3) GET ROOM (used by Room Waiting screen to poll for new players)
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.get("/rooms/:roomCode", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roomCode } = req.params;

// // // // // // // // // // // // // // // // // //     const [rooms] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT * FROM word_scramble_rooms WHERE room_code = ?`,
// // // // // // // // // // // // // // // // // //       [roomCode]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     if (rooms.length === 0) {
// // // // // // // // // // // // // // // // // //       return res.status(404).json({ error: "Room not found" });
// // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // //     const room = rooms[0];

// // // // // // // // // // // // // // // // // //     const [players] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT id, player_name, is_ready, score FROM word_scramble_players WHERE room_id = ?`,
// // // // // // // // // // // // // // // // // //       [room.id]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     return res.status(200).json({
// // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // //       room: {
// // // // // // // // // // // // // // // // // //         id: room.id,
// // // // // // // // // // // // // // // // // //         roomCode: room.room_code,
// // // // // // // // // // // // // // // // // //         roomName: room.room_name,
// // // // // // // // // // // // // // // // // //         roomType: room.room_type,
// // // // // // // // // // // // // // // // // //         maxPlayers: room.max_players,
// // // // // // // // // // // // // // // // // //         status: room.status,
// // // // // // // // // // // // // // // // // //         players,
// // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Get room error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to fetch room" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 4) LEADERBOARD (Top Players on Home screen)
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.get("/leaderboard", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const [rows] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT player_name, SUM(score) AS total_score
// // // // // // // // // // // // // // // // // //        FROM word_scramble_players
// // // // // // // // // // // // // // // // // //        GROUP BY player_name
// // // // // // // // // // // // // // // // // //        ORDER BY total_score DESC
// // // // // // // // // // // // // // // // // //        LIMIT 10`
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     return res.status(200).json({
// // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // //       players: rows.map((r, i) => ({
// // // // // // // // // // // // // // // // // //         rank: i + 1,
// // // // // // // // // // // // // // // // // //         name: r.player_name,
// // // // // // // // // // // // // // // // // //         score: r.total_score,
// // // // // // // // // // // // // // // // // //       })),
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Leaderboard error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to fetch leaderboard" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 5) START GAME (host presses "Start Game")
// // // // // // // // // // // // // // // // // // // Creates round 1 and marks room in_progress
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.post("/rooms/:roomCode/start", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roomCode } = req.params;

// // // // // // // // // // // // // // // // // //     const [rooms] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT * FROM word_scramble_rooms WHERE room_code = ?`,
// // // // // // // // // // // // // // // // // //       [roomCode]
// // // // // // // // // // // // // // // // // //     );
// // // // // // // // // // // // // // // // // //     if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });
// // // // // // // // // // // // // // // // // //     const room = rooms[0];

// // // // // // // // // // // // // // // // // //     await db.query(`UPDATE word_scramble_rooms SET status = 'in_progress' WHERE id = ?`, [room.id]);

// // // // // // // // // // // // // // // // // //     const { word, scrambled } = pickRandomWord();

// // // // // // // // // // // // // // // // // //     const [roundResult] = await db.query(
// // // // // // // // // // // // // // // // // //       `INSERT INTO word_scramble_rounds (room_id, round_number, word, scrambled, time_limit_sec)
// // // // // // // // // // // // // // // // // //        VALUES (?, 1, ?, ?, ?)`,
// // // // // // // // // // // // // // // // // //       [room.id, word, scrambled, ROUND_TIME_LIMIT_SEC]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     return res.status(201).json({
// // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // //       round: {
// // // // // // // // // // // // // // // // // //         id: roundResult.insertId,
// // // // // // // // // // // // // // // // // //         roundNumber: 1,
// // // // // // // // // // // // // // // // // //         totalRounds: TOTAL_ROUNDS,
// // // // // // // // // // // // // // // // // //         scrambled,
// // // // // // // // // // // // // // // // // //         timeLimitSec: ROUND_TIME_LIMIT_SEC,
// // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Start game error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to start game" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 6) SUBMIT ANSWER for a round
// // // // // // // // // // // // // // // // // // // Frontend sends: { playerName, answer, timeTakenSec }
// // // // // // // // // // // // // // // // // // // Backend: checks correctness, computes points, saves to DB, updates player's total score
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.post("/rounds/:roundId/answer", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roundId } = req.params;
// // // // // // // // // // // // // // // // // //     const { playerName, answer, timeTakenSec } = req.body;

// // // // // // // // // // // // // // // // // //     const [rounds] = await db.query(`SELECT * FROM word_scramble_rounds WHERE id = ?`, [roundId]);
// // // // // // // // // // // // // // // // // //     if (rounds.length === 0) return res.status(404).json({ error: "Round not found" });
// // // // // // // // // // // // // // // // // //     const round = rounds[0];

// // // // // // // // // // // // // // // // // //     const isCorrect = String(answer).trim().toUpperCase() === round.word.toUpperCase();
// // // // // // // // // // // // // // // // // //     // Faster + correct = more points. Wrong = 0.
// // // // // // // // // // // // // // // // // //     const points = isCorrect
// // // // // // // // // // // // // // // // // //       ? Math.max(20, 100 - Math.round((timeTakenSec || 0) * 5))
// // // // // // // // // // // // // // // // // //       : 0;

// // // // // // // // // // // // // // // // // //     await db.query(
// // // // // // // // // // // // // // // // // //       `INSERT INTO word_scramble_answers (round_id, player_name, answer, is_correct, time_taken_sec, points)
// // // // // // // // // // // // // // // // // //        VALUES (?, ?, ?, ?, ?, ?)`,
// // // // // // // // // // // // // // // // // //       [roundId, playerName, answer, isCorrect, timeTakenSec || 0, points]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     if (points > 0) {
// // // // // // // // // // // // // // // // // //       await db.query(
// // // // // // // // // // // // // // // // // //         `UPDATE word_scramble_players SET score = score + ? WHERE room_id = ? AND player_name = ?`,
// // // // // // // // // // // // // // // // // //         [points, round.room_id, playerName]
// // // // // // // // // // // // // // // // // //       );
// // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // //     return res.status(200).json({ success: true, isCorrect, points });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Submit answer error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to submit answer" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 7) ROUND RESULTS (Round Complete screen polls this)
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.get("/rounds/:roundId/results", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roundId } = req.params;

// // // // // // // // // // // // // // // // // //     const [rounds] = await db.query(`SELECT * FROM word_scramble_rounds WHERE id = ?`, [roundId]);
// // // // // // // // // // // // // // // // // //     if (rounds.length === 0) return res.status(404).json({ error: "Round not found" });
// // // // // // // // // // // // // // // // // //     const round = rounds[0];

// // // // // // // // // // // // // // // // // //     const [answers] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT player_name, is_correct, time_taken_sec, points
// // // // // // // // // // // // // // // // // //        FROM word_scramble_answers WHERE round_id = ? ORDER BY points DESC`,
// // // // // // // // // // // // // // // // // //       [roundId]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     const [players] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT player_name, score FROM word_scramble_players WHERE room_id = ? ORDER BY score DESC`,
// // // // // // // // // // // // // // // // // //       [round.room_id]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     return res.status(200).json({
// // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // //       word: round.word,
// // // // // // // // // // // // // // // // // //       roundNumber: round.round_number,
// // // // // // // // // // // // // // // // // //       totalRounds: TOTAL_ROUNDS,
// // // // // // // // // // // // // // // // // //       answers,
// // // // // // // // // // // // // // // // // //       standings: players,
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Round results error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to fetch round results" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 8) NEXT ROUND (or finish the game after TOTAL_ROUNDS)
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.post("/rooms/:roomCode/next-round", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roomCode } = req.params;

// // // // // // // // // // // // // // // // // //     const [rooms] = await db.query(`SELECT * FROM word_scramble_rooms WHERE room_code = ?`, [roomCode]);
// // // // // // // // // // // // // // // // // //     if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });
// // // // // // // // // // // // // // // // // //     const room = rooms[0];

// // // // // // // // // // // // // // // // // //     const [lastRoundRows] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT * FROM word_scramble_rounds WHERE room_id = ? ORDER BY round_number DESC LIMIT 1`,
// // // // // // // // // // // // // // // // // //       [room.id]
// // // // // // // // // // // // // // // // // //     );
// // // // // // // // // // // // // // // // // //     const lastRoundNumber = lastRoundRows.length > 0 ? lastRoundRows[0].round_number : 0;
// // // // // // // // // // // // // // // // // //     const nextRoundNumber = lastRoundNumber + 1;

// // // // // // // // // // // // // // // // // //     if (nextRoundNumber > TOTAL_ROUNDS) {
// // // // // // // // // // // // // // // // // //       await db.query(`UPDATE word_scramble_rooms SET status = 'finished' WHERE id = ?`, [room.id]);
// // // // // // // // // // // // // // // // // //       return res.status(200).json({ success: true, finished: true });
// // // // // // // // // // // // // // // // // //     }

// // // // // // // // // // // // // // // // // //     const [previousWords] = await db.query(
// // // // // // // // // // // // // // // // // //       `SELECT word FROM word_scramble_rounds WHERE room_id = ?`,
// // // // // // // // // // // // // // // // // //       [room.id]
// // // // // // // // // // // // // // // // // //     );
// // // // // // // // // // // // // // // // // //     const { word, scrambled } = pickRandomWord(previousWords.map((r) => r.word));

// // // // // // // // // // // // // // // // // //     const [roundResult] = await db.query(
// // // // // // // // // // // // // // // // // //       `INSERT INTO word_scramble_rounds (room_id, round_number, word, scrambled, time_limit_sec)
// // // // // // // // // // // // // // // // // //        VALUES (?, ?, ?, ?, ?)`,
// // // // // // // // // // // // // // // // // //       [room.id, nextRoundNumber, word, scrambled, ROUND_TIME_LIMIT_SEC]
// // // // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // // // //     return res.status(201).json({
// // // // // // // // // // // // // // // // // //       success: true,
// // // // // // // // // // // // // // // // // //       finished: false,
// // // // // // // // // // // // // // // // // //       round: {
// // // // // // // // // // // // // // // // // //         id: roundResult.insertId,
// // // // // // // // // // // // // // // // // //         roundNumber: nextRoundNumber,
// // // // // // // // // // // // // // // // // //         totalRounds: TOTAL_ROUNDS,
// // // // // // // // // // // // // // // // // //         scrambled,
// // // // // // // // // // // // // // // // // //         timeLimitSec: ROUND_TIME_LIMIT_SEC,
// // // // // // // // // // // // // // // // // //       },
// // // // // // // // // // // // // // // // // //     });
// // // // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // // // //     console.error("Next round error:", err);
// // // // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to advance round" });
// // // // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // // 9) FINAL STANDINGS (Game Over screen)
// // // // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // // router.get("/rooms/:roomCode/final", async (req, res) => {
// // // // // // // // // // // // // // // // // //   try {
// // // // // // // // // // // // // // // // // //     const { roomCode } = req.params;

// // // // // // // // // // // // // // // // // //     const [rooms] = await db.query(`SELECT * FROM word_scramble_rooms WHERE room_code = ?`, [roomCode]);
// // // // // // // // // // // // // // // // // //     if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });
