// // // // // // // // // // // // // // // //       `SELECT player_name, message, sent_at FROM word_scramble_messages
// // // // // // // // // // // // // // // //        WHERE room_id = ? ORDER BY sent_at ASC LIMIT 100`,
// // // // // // // // // // // // // // // //       [rooms[0].id]
// // // // // // // // // // // // // // // //     );

// // // // // // // // // // // // // // // //     return res.status(200).json({ success: true, messages });
// // // // // // // // // // // // // // // //   } catch (err) {
// // // // // // // // // // // // // // // //     console.error("Fetch messages error:", err);
// // // // // // // // // // // // // // // //     return res.status(500).json({ error: "Failed to fetch messages" });
// // // // // // // // // // // // // // // //   }
// // // // // // // // // // // // // // // // });

// // // // // // // // // // // // // // // // // ---------------------------------------------
// // // // // // // // // // // // // // // // // 0) GAME CONFIG — lets frontend show real Rounds / Time-per-round
// // // // // // // // // // // // // // // // // values instead of hardcoding them (single source of truth = backend)
// // // // // // // // // // // // // // // // // ---------------------------------------------
