// // // // // // // // // // // // // RETRY ROUND
// // // // // // // // // // // // //
// // // // // // // // // // // // // WRONG ANSWER
// // // // // // // // // // // // //
// // // // // // // // // // // // // Same round number
// // // // // // // // // // // // // New question
// // // // // // // // // // // // // New scrambled word
// // // // // // // // // // // // // New clue
// // // // // // // // // // // // // New timer
// // // // // // // // // // // // //
// // // // // // // // // // // // // Example:
// // // // // // // // // // // // //
// // // // // // // // // // // // // Round 1
// // // // // // // // // // // // // WATER
// // // // // // // // // // // // //   ↓ wrong
// // // // // // // // // // // // // Round 1
// // // // // // // // // // // // // CHAIR
// // // // // // // // // // // // //
// // // // // // // // // // // // // Round number does NOT increase.
