// // // // // // // // // // // //       }

// // // // // // // // // // // //       // -----------------------------------------
// // // // // // // // // // // //       // 1. Find current round
// // // // // // // // // // // //       // -----------------------------------------
// // // // // // // // // // // //       const [roundRows] = await db.query(
// // // // // // // // // // // //         `
// // // // // // // // // // // //         SELECT *
// // // // // // // // // // // //         FROM word_scramble_rounds
// // // // // // // // // // // //         WHERE id = ?
// // // // // // // // // // // //         LIMIT 1
// // // // // // // // // // // //         `,
// // // // // // // // // // // //         [roundId]
// // // // // // // // // // // //       );

