// // // // // // // // // // // //         WHERE id = ?
// // // // // // // // // // // //         AND room_code = ?
// // // // // // // // // // // //         LIMIT 1
// // // // // // // // // // // //         `,
// // // // // // // // // // // //         [
// // // // // // // // // // // //           currentRound.room_id,
// // // // // // // // // // // //           roomCode,
// // // // // // // // // // // //         ]
// // // // // // // // // // // //       );

// // // // // // // // // // // //       if (roomRows.length === 0) {
// // // // // // // // // // // //         return res.status(404).json({
