// // // // // // // // // // // //         (
// // // // // // // // // // // //           room_id,
// // // // // // // // // // // //           round_number,
// // // // // // // // // // // //           word,
// // // // // // // // // // // //           clue,
// // // // // // // // // // // //           scrambled,
// // // // // // // // // // // //           time_limit_sec
// // // // // // // // // // // //         )
// // // // // // // // // // // //         VALUES (?, ?, ?, ?, ?, ?)
// // // // // // // // // // // //         `,
// // // // // // // // // // // //         [
// // // // // // // // // // // //           room.id,

// // // // // // // // // // // //           // SAME ROUND
// // // // // // // // // // // //           currentRound.round_number,

// // // // // // // // // // // //           word,
// // // // // // // // // // // //           clue,
// // // // // // // // // // // //           scrambled,

// // // // // // // // // // // //           config.timeLimitSec,
// // // // // // // // // // // //         ]
// // // // // // // // // // // //       );

// // // // // // // // // // // //       // -----------------------------------------
