// // // // // // // // // ---------------------------------------------
// // // // // // // // // 5) START GAME, 6) NEXT ROUND, RETRY ROUND
// // // // // // // // // ---------------------------------------------
// // // // // // // // // REMOVED FROM THIS FILE.
// // // // // // // // //
// // // // // // // // // These three routes:
// // // // // // // // //   POST /rooms/:roomCode/start
// // // // // // // // //   POST /rooms/:roomCode/next-round
// // // // // // // // //   POST /rounds/:roundId/retry
// // // // // // // // //
// // // // // // // // // used to be defined here WITHOUT any locking, which is what caused two
// // // // // // // // // players hitting "start" at the same moment to each create their own
// // // // // // // // // separate round (two different round ids, two different words/letters).
// // // // // // // // //
// // // // // // // // // They are now defined EXCLUSIVELY in wordscrambleRoundFlow.js, which wraps
// // // // // // // // // round creation in `SELECT ... FOR UPDATE` + a transaction so concurrent
// // // // // // // // // requests for the same room serialize and only ever produce ONE round.
// // // // // // // // // server.js calls registerRoundRoutes(wordScrambleRoutes) to attach them
// // // // // // // // // onto this same router before it's mounted.
// // // // // // // // //
// // // // // // // // // Do NOT re-add start/next-round/retry handlers here — if this file and
// // // // // // // // // wordscrambleRoundFlow.js both register the same path, Express only runs
// // // // // // // // // whichever was registered first, silently ignoring the other.

