// require("./wordscrambleGuestRoutes")(router);
// module.exports = router;
const express = require("express");
const router = express.Router();
const db = require("../db");
const { pickRandomWord } = require("../utils/words");
const { WORD_SCRAMBLE_DIFFICULTY_CONFIG, VALID_WORD_SCRAMBLE_DIFFICULTIES } = require("../config/wordScrambleDifficulty");
const { buildClue } = require("../utils/clue");
const { MIN_PLAYERS_TO_START } = require("../config/wordScrambleRoom");
const { generatePuzzle } = require("../utils/generatePuzzle");
const { logActivity } = require("../utils/playerActivity");

// How many letters a single player may reveal with the hint bulb in one
// round, and how many points each reveal costs them. Tune freely.
const HINTS_PER_PLAYER_PER_ROUND = 3;
const HINT_SCORE_PENALTY = 5;

// limits for the Create Room / Room Settings screens
const MIN_ROUNDS = 1;
const MAX_ROUNDS = 50;
const MIN_ROOM_PLAYERS = 2;
// Single Player room is the only room allowed to have exactly 1 player
const MIN_SINGLE_PLAYERS = 1;
const MAX_ROOM_PLAYERS = 8;
const ROOM_NAME_MAX = 30;

// Remembers which players quit a room (Exit -> "Yes" on the game screen).
// Created automatically on start-up, same style as ws_seen_words.
db.query(
  `CREATE TABLE IF NOT EXISTS ws_room_quits (
     room_id     INT NOT NULL,
     player_name VARCHAR(100) NOT NULL,
     quit_at     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
     PRIMARY KEY (room_id, player_name)
   ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci`
).catch((err) => console.warn("[wordscramble] could not create ws_room_quits:", err.message));

// Same dictionary your frontend uses to find sub-words that fit inside the
// round's letter pool (data/wordlist.json). Copy that file into
// backend/src/data/wordlist.json — without it, rounds fall back to a
// single-word puzzle (today's behaviour) instead of a crossword.
let DICTIONARY = [];
try {
  DICTIONARY = require("../data/wordlist.json");
} catch (e) {
  console.warn(
    "[wordscramble] backend/src/data/wordlist.json not found — rounds will fall back to a single word instead of a crossword layout. Copy the frontend's data/wordlist.json into backend/src/data/ to enable multi-word rounds."
  );
}



function buildRoundWords(baseWord) {
  const letters = baseWord.toUpperCase().split("");
  if (DICTIONARY.length === 0) {
    return {
      letters,
      words: [{ word: baseWord.toUpperCase(), row: 0, col: 0, direction: "across" }],
    };
  }
  const slots = generatePuzzle(letters, DICTIONARY, 6);
  return {
    letters,
    words: slots.length > 0 ? slots : [{ word: baseWord.toUpperCase(), row: 0, col: 0, direction: "across" }],
  };
}


function wordCells(slot) {
  const cells = [];
  for (let k = 0; k < slot.word.length; k++) {
    const row = slot.direction === "across" ? slot.row : slot.row + k;
    const col = slot.direction === "across" ? slot.col + k : slot.col;
    cells.push({ row, col, letter: slot.word[k].toUpperCase() });
  }
  return cells;
}


function pickInitialReveals(words, count) {
  if (!count || count <= 0) return [];
  const allCells = [];
  words.forEach((w) => wordCells(w).forEach((cell) => allCells.push(cell)));
  const shuffled = [...allCells].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, allCells.length)).map(({ row, col }) => ({ row, col }));
}

function getConfigForDifficulty(difficulty) {
  return WORD_SCRAMBLE_DIFFICULTY_CONFIG[difficulty] || WORD_SCRAMBLE_DIFFICULTY_CONFIG.easy;
}

// a room's own saved total_rounds wins; old rooms (NULL) fall back
// to the difficulty config.
function getTotalRounds(room, config) {
  return Number(room?.total_rounds) || config.rounds;
}

// How many words has this player found in the whole game (all rounds of the room)
async function countWordsFoundByPlayer(roomId, playerName) {
  const [rows] = await db.query(
    `SELECT COUNT(*) AS c
       FROM word_scramble_found_words fw
       JOIN word_scramble_rounds r ON r.id = fw.round_id
      WHERE r.room_id = ? AND fw.found_by = ?`,
    [roomId, playerName]
  );
  return Number(rows[0]?.c) || 0;
}

// Same query everywhere a room's player list is sent to the frontend:
// includes host flag + avatar colour (from the player's profile).
// avatar colour comes from a subquery (LIMIT 1) instead of a JOIN,
// so two profiles with the same name can never duplicate a player row.
const PLAYERS_SQL = `
  SELECT p.id, p.player_name, p.is_ready, p.is_host, p.score,
         (SELECT pr.avatar_color
            FROM word_scramble_profiles pr
           WHERE pr.name = p.player_name
           LIMIT 1) AS avatar_color
  FROM word_scramble_players p
  WHERE p.room_id = ?
  ORDER BY p.id ASC`;

// Random 4-digit room code
function generateRoomCode() {
  return String(Math.floor(1000 + Math.random() * 9000));
}

// Keeps generating until it finds a code not already in use.
async function generateUniqueRoomCode() {
  let attempts = 0;
  while (attempts < 10) {
    const code = generateRoomCode();
    const [existing] = await db.query(
      `SELECT id FROM word_scramble_rooms WHERE room_code = ?`,
      [code]
    );
    if (existing.length === 0) {
      return code;
    }
    attempts++;
  }
  throw new Error("Could not generate a unique room code, please try again");
}

// ONE place that builds the room JSON sent to the frontend
// (create / join / get / settings all use it).
function buildRoomPayload(room, players) {
  const config = getConfigForDifficulty(room.difficulty);
  return {
    id: room.id,
    roomCode: room.room_code,
    roomName: room.room_name,
    roomType: room.room_type,
    maxPlayers: room.max_players,
    minPlayers: MIN_PLAYERS_TO_START,
    difficulty: room.difficulty,
    status: room.status,
    totalRounds: getTotalRounds(room, config),
    timeLimitSec: Number(room.time_limit_sec) || config.timeLimitSec,
    lives: config.lives,
    players,
  };
}

// ---------------------------------------------
// 1) CREATE ROOM
//   roomName + totalRounds are compulsory.
//   Difficulty / timer are no longer chosen by the user (defaults used).
//   Flow: frontend request -> validate -> save in DB -> JSON response
// ---------------------------------------------
router.post("/rooms", async (req, res) => {
  try {
    const { roomName, roomType, maxPlayers, playerName, totalRounds } = req.body;

    if (!playerName) {
      return res.status(400).json({ success: false, error: "playerName is required" });
    }

    // room name: compulsory, max 30 characters
    const cleanName = String(roomName ?? "").trim();
    if (!cleanName) {
      return res.status(400).json({ success: false, error: "Room name is required" });
    }
    if (cleanName.length > ROOM_NAME_MAX) {
      return res
        .status(400)
        .json({ success: false, error: `Room name must be ${ROOM_NAME_MAX} characters or less` });
    }

    // rounds: compulsory, whole number 1 - 50
    const rounds = Number(totalRounds);
    if (!Number.isInteger(rounds) || rounds < MIN_ROUNDS || rounds > MAX_ROUNDS) {
      return res.status(400).json({
        success: false,
        error: `Rounds must be a whole number between ${MIN_ROUNDS} and ${MAX_ROUNDS}`,
      });
    }

    // max players: optional, default 4, between 2 and 8
    // (the "Single Player" room is the only one allowed to have exactly 1)
    const isSingleRoom = cleanName === "Single Player" && Number(maxPlayers) === 1;
    const minAllowed = isSingleRoom ? MIN_SINGLE_PLAYERS : MIN_ROOM_PLAYERS;

    const playersLimit = maxPlayers === undefined || maxPlayers === null ? 4 : Number(maxPlayers);
    if (
      !Number.isInteger(playersLimit) ||
      playersLimit < minAllowed ||
      playersLimit > MAX_ROOM_PLAYERS
    ) {
      return res.status(400).json({
        success: false,
        error: `Max players must be between ${MIN_ROOM_PLAYERS} and ${MAX_ROOM_PLAYERS}`,
      });
    }

    // difficulty + timer are not user choices any more -> defaults
    const difficulty = "easy";
    const config = getConfigForDifficulty(difficulty);
    const timeLimitSec = config.timeLimitSec;
    const type = roomType === "public" ? "public" : "private";

    const roomCode = await generateUniqueRoomCode();

    const [roomResult] = await db.query(
      `INSERT INTO word_scramble_rooms
         (room_code, room_name, room_type, max_players, difficulty, total_rounds, time_limit_sec, status)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'waiting')`,
      [roomCode, cleanName, type, playersLimit, difficulty, rounds, timeLimitSec]
    );

    const roomId = roomResult.insertId;

    // The creator is the host
    await db.query(
      `INSERT INTO word_scramble_players (room_id, player_name, is_ready, is_host)
       VALUES (?, ?, TRUE, TRUE)`,
      [roomId, playerName]
    );

    const [players] = await db.query(PLAYERS_SQL, [roomId]);

    return res.status(201).json({
      success: true,
      room: buildRoomPayload(
        {
          id: roomId,
          room_code: roomCode,
          room_name: cleanName,
          room_type: type,
          max_players: playersLimit,
          difficulty,
          status: "waiting",
          total_rounds: rounds,
          time_limit_sec: timeLimitSec,
        },
        players
      ),
    });
  } catch (err) {
    console.error("Create room error:", err);
    return res.status(500).json({ success: false, error: "Failed to create room" });
  }
});

// ---------------------------------------------
// 2) JOIN ROOM
//   Works for registered players AND guests (guest nickname is
//   just a playerName here).
// ---------------------------------------------
router.post("/rooms/:roomCode/join", async (req, res) => {
  try {
    const { roomCode } = req.params;
    const { playerName } = req.body;

    if (!playerName) {
      return res.status(400).json({ error: "playerName is required" });
    }

    const [rooms] = await db.query(
      `SELECT * FROM word_scramble_rooms WHERE room_code = ?`,
      [roomCode]
    );

    if (rooms.length === 0) {
      return res.status(404).json({ error: "Room not found" });
    }

    const room = rooms[0];

    const [existingPlayers] = await db.query(
      `SELECT * FROM word_scramble_players WHERE room_id = ?`,
      [room.id]
    );

    // Already in this room (page reload / rejoin) → don't add a duplicate row
    const alreadyIn = existingPlayers.some((p) => p.player_name === playerName);

    if (!alreadyIn) {
      if (existingPlayers.length >= room.max_players) {
        return res.status(409).json({ error: "Room is full" });
      }

      await db.query(
        `INSERT INTO word_scramble_players (room_id, player_name, is_ready, is_host)
         VALUES (?, ?, FALSE, FALSE)`,
        [room.id, playerName]
      );
    }

    // joining again clears an earlier "quit" mark for this player
    try {
      await db.query(
        `DELETE FROM ws_room_quits WHERE room_id = ? AND player_name = ?`,
        [room.id, playerName]
      );
    } catch (quitErr) {
      console.warn("Could not clear quit mark:", quitErr.message);
    }

    const [players] = await db.query(PLAYERS_SQL, [room.id]);

    return res.status(200).json({
      success: true,
      room: buildRoomPayload(room, players),
    });
  } catch (err) {
    console.error("Join room error:", err);
    return res.status(500).json({ error: "Failed to join room" });
  }
});

// ---------------------------------------------
// 3) GET ROOM (Room Waiting screen polls this)
// ---------------------------------------------
router.get("/rooms/:roomCode", async (req, res) => {
  try {
    const { roomCode } = req.params;

    const [rooms] = await db.query(
      `SELECT * FROM word_scramble_rooms WHERE room_code = ?`,
      [roomCode]
    );

    if (rooms.length === 0) {
      return res.status(404).json({ error: "Room not found" });
    }

    const room = rooms[0];

    const [players] = await db.query(PLAYERS_SQL, [room.id]);

    return res.status(200).json({
      success: true,
      room: buildRoomPayload(room, players),
    });
  } catch (err) {
    console.error("Get room error:", err);
    return res.status(500).json({ error: "Failed to fetch room" });
  }
});

// ---------------------------------------------
// 4) LEADERBOARD (Top Players on Home screen)
//
// only names that exist in the MAIN app `player` table (the name
// set in the main menu Profile screen) AND have opened Word Scramble
// (have a word_scramble_profiles row) are listed. Old random names such as
// QuietFalcon268 are never shown. A player with no games yet shows with 0 PTS.
// ---------------------------------------------
router.get("/leaderboard", async (req, res) => {
  try {
    let rows;

    try {
      [rows] = await db.query(
        `SELECT pl.name AS player_name,
                COALESCE(
                  (SELECT SUM(wp.score)
                     FROM word_scramble_players wp
                    WHERE wp.player_name = pl.name),
                  0
                ) AS total_score,
                (SELECT pr.avatar_color
                   FROM word_scramble_profiles pr
                  WHERE pr.name = pl.name
                  LIMIT 1) AS avatar_color
           FROM player pl
          WHERE EXISTS (
                  SELECT 1 FROM word_scramble_profiles pr2
                   WHERE pr2.name = pl.name
                )
          GROUP BY pl.name
          ORDER BY total_score DESC, pl.name ASC
          LIMIT 10`
      );
    } catch (joinErr) {
      // `player` table not reachable from this db connection -> old behaviour
      console.warn("Leaderboard: main player table lookup failed, using fallback:", joinErr.message);
      [rows] = await db.query(
        `SELECT player_name, SUM(score) AS total_score, NULL AS avatar_color
           FROM word_scramble_players
          GROUP BY player_name
          ORDER BY total_score DESC
          LIMIT 10`
      );
    }

    return res.status(200).json({
      success: true,
      players: rows.map((r, i) => ({
        rank: i + 1,
        name: r.player_name,
        score: Number(r.total_score) || 0,
        avatarColor: r.avatar_color || null,
      })),
    });
  } catch (err) {
    console.error("Leaderboard error:", err);
    return res.status(500).json({ error: "Failed to fetch leaderboard" });
  }
});

// ---------------------------------------------
// 4b) LEADERBOARD SCORECARD (Rankings screen)
//   GET /api/wordscramble/leaderboard/scorecard
//   Flow: frontend request -> DB queries -> JSON response
//   Every player: rank, name, score, wordsFound, coinsEarned, isWinner.
//   The Rankings screen polls this every 5 seconds (live update).
//
//   WINNER RULE: the player who found the MOST WORDS wins.
//   Tie-break: coins earned, then score, then name.
//   Players with the same words + coins + score share the same rank.
//   If nobody found a word, there is no winner (isWinner = false).
//
//   !! COINS_EARNED_SQL is the ONLY part that depends on your coins table
//   (see WordscrambleCoinsRoutes.js). Change the table / column names to
//   match. If the query fails the board still works and coinsEarned = 0.
// ---------------------------------------------
const COINS_EARNED_SQL = `
  SELECT player_name, SUM(amount) AS earned
    FROM ws_coin_transactions
   WHERE amount > 0
   GROUP BY player_name`;

router.get("/leaderboard/scorecard", async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT pl.name AS player_name,
              COALESCE(
                (SELECT SUM(wp.score)
                   FROM word_scramble_players wp
                  WHERE wp.player_name COLLATE utf8mb4_unicode_ci
                      = pl.name COLLATE utf8mb4_unicode_ci), 0
              ) AS total_score,
              (SELECT COUNT(*)
                 FROM word_scramble_found_words fw
                WHERE fw.found_by COLLATE utf8mb4_unicode_ci
                    = pl.name COLLATE utf8mb4_unicode_ci) AS words_found,
              (SELECT pr.avatar_color
                 FROM word_scramble_profiles pr
                WHERE pr.name COLLATE utf8mb4_unicode_ci
                    = pl.name COLLATE utf8mb4_unicode_ci
                LIMIT 1) AS avatar_color
         FROM player pl
        WHERE EXISTS (
                SELECT 1 FROM word_scramble_profiles pr2
                 WHERE pr2.name COLLATE utf8mb4_unicode_ci
                     = pl.name COLLATE utf8mb4_unicode_ci
              )
        GROUP BY pl.name
        ORDER BY words_found DESC, total_score DESC, pl.name ASC
        LIMIT 50`
    );

    // coins earned: separate query so a schema mismatch never breaks the board
    const coinsByPlayer = {};
    try {
      const [coinRows] = await db.query(COINS_EARNED_SQL);
      coinRows.forEach((c) => {
        coinsByPlayer[c.player_name] = Number(c.earned) || 0;
      });
    } catch (coinErr) {
      console.warn("Scorecard: coins query failed, using 0:", coinErr.message);
    }

    const players = rows.map((r) => ({
      name: r.player_name,
      score: Number(r.total_score) || 0,
      wordsFound: Number(r.words_found) || 0,
      coinsEarned: coinsByPlayer[r.player_name] || 0,
      avatarColor: r.avatar_color || null,
    }));

    // WINNER RULE: most words found wins. Tie-break: coins, then score, then name.
    players.sort(
      (a, b) =>
        b.wordsFound - a.wordsFound ||
        b.coinsEarned - a.coinsEarned ||
        b.score - a.score ||
        a.name.localeCompare(b.name)
    );

    // same words + coins + score = same rank (shared place)
    let rank = 0;
    players.forEach((p, i) => {
      const prev = players[i - 1];
      const tied =
        prev &&
        prev.wordsFound === p.wordsFound &&
        prev.coinsEarned === p.coinsEarned &&
        prev.score === p.score;
      if (!tied) rank = i + 1;
      p.rank = rank;
      p.isWinner = rank === 1 && p.wordsFound > 0; // nobody found a word = no winner
    });

    return res.status(200).json({ success: true, players });
  } catch (err) {
    console.error("Scorecard error:", err);
    return res.status(500).json({ error: "Failed to fetch scorecard" });
  }
});

router.get("/rounds/:roundId/results", async (req, res) => {
  try {
    const { roundId } = req.params;

    const [rounds] = await db.query(`SELECT * FROM word_scramble_rounds WHERE id = ?`, [roundId]);
    if (rounds.length === 0) return res.status(404).json({ error: "Round not found" });
    const round = rounds[0];

    const [roomRows] = await db.query(
      `SELECT difficulty, total_rounds FROM word_scramble_rooms WHERE id = ?`,
      [round.room_id]
    );
    const config = getConfigForDifficulty(roomRows[0]?.difficulty);

    const [answers] = await db.query(
      `SELECT player_name, answer, is_correct, time_taken_sec, points
       FROM word_scramble_answers WHERE round_id = ? ORDER BY points DESC`,
      [roundId]
    );

    const [players] = await db.query(
      `SELECT player_name, score FROM word_scramble_players WHERE room_id = ? ORDER BY score DESC`,
      [round.room_id]
    );

    return res.status(200).json({
      success: true,
      word: round.word,
      roundNumber: round.round_number,
      totalRounds: getTotalRounds(roomRows[0], config),
      answers,
      standings: players,
    });
  } catch (err) {
    console.error("Round results error:", err);
    return res.status(500).json({ error: "Failed to fetch round results" });
  }
});

// ---------------------------------------------
// 8) FINAL STANDINGS (Game Over screen)
// ---------------------------------------------
router.get("/rooms/:roomCode/final", async (req, res) => {
  try {
    const { roomCode } = req.params;

    const [rooms] = await db.query(`SELECT * FROM word_scramble_rooms WHERE room_code = ?`, [roomCode]);
    if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });
    const room = rooms[0];
    const config = getConfigForDifficulty(room.difficulty);

    const [players] = await db.query(
      `SELECT player_name, score FROM word_scramble_players WHERE room_id = ? ORDER BY score DESC`,
      [room.id]
    );

    const [fastest] = await db.query(
      `SELECT a.player_name, MIN(a.time_taken_sec) AS best_time
       FROM word_scramble_answers a
       JOIN word_scramble_rounds r ON a.round_id = r.id
       WHERE r.room_id = ? AND a.is_correct = TRUE
       ORDER BY best_time ASC LIMIT 1`,
      [room.id]
    );

    return res.status(200).json({
      success: true,
      standings: players,
      fastestAnswer: fastest[0] || null,
      totalRounds: getTotalRounds(room, config),
    });
  } catch (err) {
    console.error("Final standings error:", err);
    return res.status(500).json({ error: "Failed to fetch final standings" });
  }
});

// ---------------------------------------------
// 9) CHAT — send + fetch messages
// ---------------------------------------------
router.post("/rooms/:roomCode/messages", async (req, res) => {
  try {
    const { roomCode } = req.params;
    const { playerName, message } = req.body;

    const [rooms] = await db.query(`SELECT * FROM word_scramble_rooms WHERE room_code = ?`, [roomCode]);
    if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });

    await db.query(
      `INSERT INTO word_scramble_messages (room_id, player_name, message) VALUES (?, ?, ?)`,
      [rooms[0].id, playerName, message]
    );

    return res.status(201).json({ success: true });
  } catch (err) {
    console.error("Send message error:", err);
    return res.status(500).json({ error: "Failed to send message" });
  }
});

router.get("/rooms/:roomCode/messages", async (req, res) => {
  try {
    const { roomCode } = req.params;

    const [rooms] = await db.query(`SELECT * FROM word_scramble_rooms WHERE room_code = ?`, [roomCode]);
    if (rooms.length === 0) return res.status(404).json({ error: "Room not found" });

    const [messages] = await db.query(
      `SELECT player_name, message, sent_at FROM word_scramble_messages
       WHERE room_id = ? ORDER BY sent_at ASC LIMIT 100`,
      [rooms[0].id]
    );

    return res.status(200).json({ success: true, messages });
  } catch (err) {
    console.error("Fetch messages error:", err);
    return res.status(500).json({ error: "Failed to fetch messages" });
  }
});

// ---------------------------------------------
// 10) GAME CONFIG — GET /config/easy | medium | hard
// ---------------------------------------------
router.get("/config/:difficulty", (req, res) => {
  const { difficulty } = req.params;

  if (!VALID_WORD_SCRAMBLE_DIFFICULTIES.includes(difficulty)) {
    return res.status(400).json({
      error: `Invalid difficulty. Must be one of: ${VALID_WORD_SCRAMBLE_DIFFICULTIES.join(", ")}`,
    });
  }

  const config = getConfigForDifficulty(difficulty);
  return res.status(200).json({
    success: true,
    difficulty,
    label: config.label,
    totalRounds: config.rounds,
    timeLimitSec: config.timeLimitSec,
    lives: config.lives,
    freeReveals: config.freeReveals,
  });
});

// ---------------------------------------------
// WORD BANK — list / add / delete words
// ---------------------------------------------
router.get("/words", async (req, res) => {
  try {
    const { difficulty } = req.query;

    let sql = "SELECT id, word, clue, difficulty, created_at FROM word_scramble_words";
    const params = [];

    if (difficulty) {
      if (!VALID_WORD_SCRAMBLE_DIFFICULTIES.includes(difficulty)) {
        return res.status(400).json({
          error: `Invalid difficulty. Must be one of: ${VALID_WORD_SCRAMBLE_DIFFICULTIES.join(", ")}`,
        });
      }
      sql += " WHERE difficulty = ?";
      params.push(difficulty);
    }

    sql += " ORDER BY created_at DESC";

    const [words] = await db.query(sql, params);

    return res.status(200).json({ success: true, words });
  } catch (err) {
    console.error("Fetch words error:", err);
    return res.status(500).json({ error: "Failed to fetch words" });
  }
});

router.post("/words", async (req, res) => {
  try {
    const { word, clue, difficulty } = req.body;

    if (!word || !clue) {
      return res.status(400).json({ error: "word and clue are required" });
    }

    const validDifficulty = VALID_WORD_SCRAMBLE_DIFFICULTIES.includes(difficulty)
      ? difficulty
      : "easy";

    const [result] = await db.query(
      `INSERT INTO word_scramble_words (word, clue, difficulty) VALUES (?, ?, ?)`,
      [word.trim().toUpperCase(), clue.trim(), validDifficulty]
    );

    return res.status(201).json({
      success: true,
      wordEntry: {
        id: result.insertId,
        word: word.trim().toUpperCase(),
        clue: clue.trim(),
        difficulty: validDifficulty,
      },
    });
  } catch (err) {
    console.error("Add word error:", err);
    return res.status(500).json({ error: "Failed to add word" });
  }
});

router.delete("/words/:id", async (req, res) => {
  try {
    const { id } = req.params;

    const [result] = await db.query(`DELETE FROM word_scramble_words WHERE id = ?`, [id]);

    if (result.affectedRows === 0) {
      return res.status(404).json({ error: "Word not found" });
    }

    return res.status(200).json({ success: true, deletedId: Number(id) });
  } catch (err) {
    console.error("Delete word error:", err);
    return res.status(500).json({ error: "Failed to delete word" });
  }
});

// ---------------------------------------------
// 11) SUBMIT ANSWER — checks against the round's full word LIST
//   (words_json), not just the single `word` column. A round can have
//   several correct answers; each one found earns points once.
//   Response also carries myWordsFound (this player's total words found).
// ---------------------------------------------
router.post("/rounds/:roundId/answer", async (req, res) => {
  try {
    const { roundId } = req.params;
    const { playerName, answer, timeTakenSec } = req.body;

    if (!playerName) {
      return res.status(400).json({ error: "playerName is required" });
    }
    if (answer === undefined || answer === null) {
      return res.status(400).json({ error: "answer is required" });
    }

    // 1. Get current round
    const [rounds] = await db.query(
      `SELECT * FROM word_scramble_rounds WHERE id = ? LIMIT 1`,
      [roundId]
    );
    if (rounds.length === 0) {
      return res.status(404).json({ error: "Round not found" });
    }
    const round = rounds[0];

    // 2. Load this round's word list (falls back to the single legacy
    // `word` column for rounds created before this migration)
    let words = [];
    try {
      words = JSON.parse(round.words_json || "[]");
    } catch (e) {
      words = [];
    }
    if (words.length === 0 && round.word) {
      words = [{ word: round.word, row: 0, col: 0, direction: "across" }];
    }

    const userAnswer = String(answer).trim().toUpperCase();
    const matchedSlot = words.find((w) => String(w.word).toUpperCase() === userAnswer);
    const isCorrect = !!matchedSlot;

    const seconds = Number(timeTakenSec) || 0;
    let points = 0;
    const connection = await db.getConnection();
    try {
      await connection.beginTransaction();

      let newlyFound = false;
      if (isCorrect) {
        const [foundResult] = await connection.query(
          `INSERT IGNORE INTO word_scramble_found_words (round_id, word, found_by)
           VALUES (?, ?, ?)`,
          [roundId, userAnswer, playerName]
        );
        newlyFound = foundResult.affectedRows === 1;
      }

      // Only the first correct find earns points and coins.
      points = newlyFound ? Math.max(20, 100 - Math.round(seconds * 5)) : 0;

      await connection.query(
        `INSERT INTO word_scramble_answers
          (round_id, player_name, answer, is_correct, time_taken_sec, points)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [roundId, playerName, answer, isCorrect, seconds, points]
      );

      if (newlyFound) {
        await connection.query(
          `UPDATE word_scramble_players SET score = score + ? WHERE room_id = ? AND player_name = ?`,
          [points, round.room_id, playerName]
        );

      }

      await connection.commit();
    } catch (transactionError) {
      await connection.rollback();
      throw transactionError;
    } finally {
      connection.release();
    }

    // 5. Lives come from the room's difficulty config (not hardcoded)
    const [roomRows] = await db.query(
      `SELECT difficulty FROM word_scramble_rooms WHERE id = ? LIMIT 1`,
      [round.room_id]
    );
    if (roomRows.length === 0) {
      return res.status(404).json({ error: "Room not found" });
    }
    const config = getConfigForDifficulty(roomRows[0].difficulty);

    const [wrongRows] = await db.query(
      `SELECT COUNT(*) AS wrong_count
       FROM word_scramble_answers a
       INNER JOIN word_scramble_rounds r ON a.round_id = r.id
       WHERE r.room_id = ? AND a.player_name = ? AND a.is_correct = FALSE`,
      [round.room_id, playerName]
    );
    const wrongCount = Number(wrongRows[0]?.wrong_count) || 0;
    const livesLeft = Math.max(0, config.lives - wrongCount);

    // 6. Round-wide progress (used by GamePlayScreen's grid / progress bar)
    const [foundRows] = await db.query(
      `SELECT word, found_by AS foundBy FROM word_scramble_found_words WHERE round_id = ?`,
      [roundId]
    );
    const isRoundComplete = foundRows.length >= words.length;

    // this player's total found-words count (shown at the top of the game screen)
    const myWordsFound = await countWordsFoundByPlayer(round.room_id, playerName);

    // round fully solved -> everybody in the room is now on the next round
    if (isRoundComplete) {
      try {
        await db.query(
          `INSERT INTO ws_player_progress (player_name, next_round)
           SELECT player_name, ? FROM word_scramble_players WHERE room_id = ?
           ON DUPLICATE KEY UPDATE next_round = GREATEST(next_round, VALUES(next_round))`,
          [round.round_number + 1, round.room_id]
        );
      } catch (progressError) {
        console.error("Saving progress failed:", progressError);
      }
    }

    const completedEvent = isRoundComplete
      ? {
          type: "game_win",
          detail: `Completed round ${round.round_number}`,
          activityKey: `word-scramble:round:${roundId}`,
        }
      : !isCorrect && wrongCount === config.lives
        ? {
            type: "game_lose",
            detail: `Ran out of lives in room ${round.room_id}`,
            activityKey: `word-scramble:room:${round.room_id}:loss`,
          }
        : null;

    if (completedEvent) {
      try {
        const [playerRows] = await db.query(
          `SELECT score FROM word_scramble_players WHERE room_id = ? AND player_name = ? LIMIT 1`,
          [round.room_id, playerName]
        );

        await logActivity({
          game: "word-scramble",
          type: completedEvent.type,
          value: Number(playerRows[0]?.score) || 0,
          detail: completedEvent.detail,
          activityKey: completedEvent.activityKey,
        });
      } catch (activityError) {
        console.error("Word Scramble activity log failed:", activityError);
      }
    }

    return res.status(200).json({
      success: true,
      isCorrect,
      points,
      livesLeft,
      wordsFound: foundRows.length,
      myWordsFound,
      totalWords: words.length,
      foundWords: foundRows,
      isRoundComplete,
    });
  } catch (err) {
    console.error("Submit answer error:", err);
    return res.status(500).json({
      error: "Failed to submit answer",
      details: err.message,
    });
  }
});

// ---------------------------------------------
// 11b) HINT — reveal one more letter in the shared grid.
//   POST /api/wordscramble/rounds/:roundId/hint
//   body: { playerName }
// ---------------------------------------------
router.post("/rounds/:roundId/hint", async (req, res) => {
  try {
    const { roundId } = req.params;
    const { playerName } = req.body;

    if (!playerName) {
      return res.status(400).json({ error: "playerName is required" });
    }

    const [roundRows] = await db.query(
      `SELECT * FROM word_scramble_rounds WHERE id = ? LIMIT 1`,
      [roundId]
    );
    if (roundRows.length === 0) {
      return res.status(404).json({ error: "Round not found" });
    }
    const round = roundRows[0];

    let words = [];
    try {
      words = JSON.parse(round.words_json || "[]");
    } catch (e) {
      words = [];
    }
    if (words.length === 0 && round.word) {
      words = [{ word: round.word, row: 0, col: 0, direction: "across" }];
    }

    // How many hints has THIS player already burned this round?
    const [usedRows] = await db.query(
      `SELECT COUNT(*) AS c FROM word_scramble_hints WHERE round_id = ? AND player_name = ?`,
      [roundId, playerName]
    );
    const hintsUsed = Number(usedRows[0]?.c) || 0;

    if (hintsUsed >= HINTS_PER_PLAYER_PER_ROUND) {
      return res.status(409).json({ error: "No hints left this round", hintsLeft: 0 });
    }

    // Cells that are already visible for everyone: the free starter
    // reveals from round creation, any hint any player has used so far,
    // and every cell belonging to a word that's already been fully found.
    let initialReveals = [];
    try {
      initialReveals = JSON.parse(round.revealed_json || "[]");
    } catch (e) {
      initialReveals = [];
    }

    const [hintRows] = await db.query(
      `SELECT row, col FROM word_scramble_hints WHERE round_id = ?`,
      [roundId]
    );
    const [foundRows] = await db.query(
      `SELECT word FROM word_scramble_found_words WHERE round_id = ?`,
      [roundId]
    );
    const foundWordsUpper = new Set(foundRows.map((r) => String(r.word).toUpperCase()));

    const revealedKeys = new Set([
      ...initialReveals.map((c) => `${c.row}-${c.col}`),
      ...hintRows.map((c) => `${c.row}-${c.col}`),
    ]);

    const candidates = [];
    words.forEach((w) => {
      if (foundWordsUpper.has(String(w.word).toUpperCase())) return;
      wordCells(w).forEach((cell) => {
        const key = `${cell.row}-${cell.col}`;
        if (!revealedKeys.has(key)) candidates.push(cell);
      });
    });

    if (candidates.length === 0) {
      // Nothing left to reveal (player's basically solved it already)
      return res.status(200).json({
        success: true,
        exhausted: true,
        hintsLeft: HINTS_PER_PLAYER_PER_ROUND - hintsUsed,
      });
    }

    const pick = candidates[Math.floor(Math.random() * candidates.length)];

    await db.query(
      `INSERT INTO word_scramble_hints (round_id, player_name, row, col, letter) VALUES (?, ?, ?, ?, ?)`,
      [roundId, playerName, pick.row, pick.col, pick.letter]
    );

    await db.query(
      `UPDATE word_scramble_players SET score = GREATEST(0, score - ?) WHERE room_id = ? AND player_name = ?`,
      [HINT_SCORE_PENALTY, round.room_id, playerName]
    );

    return res.status(200).json({
      success: true,
      revealed: pick, // { row, col, letter }
      scorePenalty: HINT_SCORE_PENALTY,
      hintsLeft: HINTS_PER_PLAYER_PER_ROUND - (hintsUsed + 1),
    });
  } catch (err) {
    console.error("Hint error:", err);
    return res.status(500).json({ error: "Failed to reveal hint" });
  }
});

// ---------------------------------------------
// 11c) ROUND STATE — polled by every client every few seconds so a word
//   one player finds (or a hint one player reveals) shows up for everyone
//   else too. This is what makes it "multiplayer" instead of each player
//   playing their own private copy of the same starting puzzle.
//   GET /rounds/:roundId/state?playerName=X
//   Every player carries wordsFound, and the caller gets myWordsFound.
// ---------------------------------------------
router.get("/rounds/:roundId/state", async (req, res) => {
  try {
    const { roundId } = req.params;
    const { playerName } = req.query;

    const [roundRows] = await db.query(
      `SELECT * FROM word_scramble_rounds WHERE id = ? LIMIT 1`,
      [roundId]
    );
    if (roundRows.length === 0) return res.status(404).json({ error: "Round not found" });
    const round = roundRows[0];

    let words = [];
    try {
      words = JSON.parse(round.words_json || "[]");
    } catch (e) {
      words = [];
    }
    if (words.length === 0 && round.word) {
      words = [{ word: round.word, row: 0, col: 0, direction: "across" }];
    }

    // Every word ANY player has found so far in this round
    const [foundRows] = await db.query(
      `SELECT word, found_by AS foundBy FROM word_scramble_found_words WHERE round_id = ?`,
      [roundId]
    );

    // Starter reveals (same for everyone, set at round creation) + every
    // hint ANY player has used so far — union of both is what should be
    // visible on every client's grid right now.
    let initialReveals = [];
    try {
      initialReveals = JSON.parse(round.revealed_json || "[]");
    } catch (e) {
      initialReveals = [];
    }
    const [hintRows] = await db.query(
      `SELECT row, col FROM word_scramble_hints WHERE round_id = ?`,
      [roundId]
    );
    const revealedCells = [
      ...initialReveals,
      ...hintRows.map((h) => ({ row: h.row, col: h.col })),
    ];

    const [roomRows] = await db.query(
      `SELECT id, difficulty FROM word_scramble_rooms WHERE id = ? LIMIT 1`,
      [round.room_id]
    );
    const config = getConfigForDifficulty(roomRows[0]?.difficulty);

    // Live scoreboard for the Players sidebar
    // each player also carries how many words they have found
    const [playerRows] = await db.query(
      `SELECT p.player_name, p.score,
              (SELECT COUNT(*)
                 FROM word_scramble_found_words fw
                 JOIN word_scramble_rounds r2 ON r2.id = fw.round_id
                WHERE r2.room_id = p.room_id AND fw.found_by = p.player_name) AS words_found
         FROM word_scramble_players p
        WHERE p.room_id = ?
        ORDER BY p.score DESC`,
      [round.room_id]
    );
    const players = playerRows.map((p) => ({
      player_name: p.player_name,
      score: Number(p.score) || 0,
      wordsFound: Number(p.words_found) || 0,
    }));
    const myWordsFound = playerName
      ? players.find((p) => p.player_name === playerName)?.wordsFound ?? 0
      : null;

    // Per-caller values (lives / hints left are personal, not shared)
    let livesLeft = null;
    let hintsLeftForPlayer = null;
    if (playerName) {
      const [wrongRows] = await db.query(
        `SELECT COUNT(*) AS wrong_count
         FROM word_scramble_answers a
         INNER JOIN word_scramble_rounds r ON a.round_id = r.id
         WHERE r.room_id = ? AND a.player_name = ? AND a.is_correct = FALSE`,
        [round.room_id, playerName]
      );
      const wrongCount = Number(wrongRows[0]?.wrong_count) || 0;
      livesLeft = Math.max(0, config.lives - wrongCount);

      const [usedHintRows] = await db.query(
        `SELECT COUNT(*) AS c FROM word_scramble_hints WHERE round_id = ? AND player_name = ?`,
        [roundId, playerName]
      );
      hintsLeftForPlayer = Math.max(0, HINTS_PER_PLAYER_PER_ROUND - (Number(usedHintRows[0]?.c) || 0));
    }

    return res.status(200).json({
      success: true,
      roundId: round.id,
      foundWords: foundRows, // [{ word, foundBy }]
      revealedCells, // [{ row, col }]
      totalWords: words.length,
      isRoundComplete: foundRows.length >= words.length,
      players, // [{ player_name, score, wordsFound }]
      myWordsFound,
      livesLeft,
      hintsLeftForPlayer,
    });
  } catch (err) {
    console.error("Round state error:", err);
    return res.status(500).json({ error: "Failed to fetch round state" });
  }
});

// ---------------------------------------------
// QUIT GAME — player taps Exit on the game screen and answers "Yes".
//   POST /api/wordscramble/rounds/:roundId/quit
//   body: { playerName }
//   Flow: frontend request -> backend saves the quit in DB -> JSON response.
//   When EVERY player of the room has quit, the room is marked 'finished'
//   (so the app does not drag a single player back into the game on restart).
//   Level progress (ws_player_progress) is kept, so the next game continues
//   from the same level.
// ---------------------------------------------
router.post("/rounds/:roundId/quit", async (req, res) => {
  try {
    const { roundId } = req.params;
    const { playerName } = req.body || {};

    if (!playerName) {
      return res.status(400).json({ success: false, error: "playerName is required" });
    }

    const [roundRows] = await db.query(
      `SELECT room_id FROM word_scramble_rounds WHERE id = ? LIMIT 1`,
      [roundId]
    );
    if (roundRows.length === 0) {
      return res.status(404).json({ success: false, error: "Round not found" });
    }
    const roomId = roundRows[0].room_id;

    const [member] = await db.query(
      `SELECT id FROM word_scramble_players WHERE room_id = ? AND player_name = ? LIMIT 1`,
      [roomId, playerName]
    );
    if (member.length === 0) {
      return res.status(403).json({ success: false, error: "You are not in this room" });
    }

    await db.query(
      `INSERT IGNORE INTO ws_room_quits (room_id, player_name) VALUES (?, ?)`,
      [roomId, playerName]
    );

    const [counts] = await db.query(
      `SELECT
         (SELECT COUNT(*) FROM word_scramble_players WHERE room_id = ?) AS total,
         (SELECT COUNT(*) FROM ws_room_quits WHERE room_id = ?) AS quits`,
      [roomId, roomId]
    );
    const total = Number(counts[0]?.total) || 0;
    const quits = Number(counts[0]?.quits) || 0;
    const roomFinished = total > 0 && quits >= total;

    if (roomFinished) {
      await db.query(
        `UPDATE word_scramble_rooms SET status = 'finished' WHERE id = ? AND status <> 'finished'`,
        [roomId]
      );
    }

    return res.status(200).json({ success: true, roomFinished });
  } catch (err) {
    console.error("Quit game error:", err);
    return res.status(500).json({ success: false, error: "Failed to quit the game" });
  }
});

// ---------------------------------------------
// SETTINGS — host can change total rounds pre-game
//   rounds validated 1 - 50. timePerRoundSec is now OPTIONAL
//   (timer was removed from the UI) - if it is missing the room keeps
//   its current time_limit_sec.
// ---------------------------------------------
router.patch("/rooms/:roomCode/settings", async (req, res) => {
  try {
    const { roomCode } = req.params;
    const { playerName, totalRounds, timePerRoundSec } = req.body;

    if (!playerName) {
      return res.status(400).json({ error: "playerName is required" });
    }

    const rounds = Number(totalRounds);
    if (!Number.isInteger(rounds) || rounds < MIN_ROUNDS || rounds > MAX_ROUNDS) {
      return res.status(400).json({
        error: `Rounds must be a whole number between ${MIN_ROUNDS} and ${MAX_ROUNDS}`,
      });
    }

    const [rooms] = await db.query(
      `SELECT * FROM word_scramble_rooms WHERE room_code = ?`,
      [roomCode]
    );
    if (rooms.length === 0) {
      return res.status(404).json({ error: "Room not found" });
    }
    const room = rooms[0];
    const config = getConfigForDifficulty(room.difficulty);

    // Only the host can change settings
    const [hostRows] = await db.query(
      `SELECT player_name FROM word_scramble_players WHERE room_id = ? AND is_host = TRUE LIMIT 1`,
      [room.id]
    );
    if (hostRows.length === 0 || hostRows[0].player_name !== playerName) {
      return res.status(403).json({ error: "Only the host can update settings" });
    }

    // Only while the room is still waiting to start
    if (room.status !== "waiting") {
      return res.status(409).json({ error: "Cannot change settings after the game has started" });
    }

    const requestedTime = Number(timePerRoundSec);
    const timeLimitSec =
      Number.isFinite(requestedTime) && requestedTime > 0
        ? requestedTime
        : Number(room.time_limit_sec) || config.timeLimitSec;

    await db.query(
      `UPDATE word_scramble_rooms SET total_rounds = ?, time_limit_sec = ? WHERE id = ?`,
      [rounds, timeLimitSec, room.id]
    );

    const [players] = await db.query(PLAYERS_SQL, [room.id]);

    return res.status(200).json({
      success: true,
      room: {
        ...buildRoomPayload(
          { ...room, total_rounds: rounds, time_limit_sec: timeLimitSec },
          players
        ),
        timePerRoundSec: timeLimitSec,
      },
    });
  } catch (err) {
    console.error("Update room settings error:", err);
    return res.status(500).json({ error: "Failed to update settings" });
  }
});

// ---------------------------------------------
// ACTIVE ROOM — which unfinished room is this player still in?
//   GET /active-room/:playerName
//   Used by the frontend resume logic (other device / cleared storage).
//   Rooms the player already QUIT are not returned any more.
// ---------------------------------------------
router.get("/active-room/:playerName", async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT r.room_code
         FROM word_scramble_rooms r
         JOIN word_scramble_players p ON p.room_id = r.id
        WHERE p.player_name = ?
          AND r.status <> 'finished'
          AND NOT EXISTS (
                SELECT 1 FROM ws_room_quits q
                 WHERE q.room_id = r.id AND q.player_name = p.player_name
              )
        ORDER BY r.id DESC
        LIMIT 1`,
      [req.params.playerName]
    );
    return res.json({ roomCode: rows[0]?.room_code ?? null });
  } catch (e) {
    console.error("Active room error:", e);
    return res.status(500).json({ error: "Failed to load active room" });
  }
});
require("./wordscrambleGuestRoutes")(router);
module.exports = router;